select 39 as n, row_number() over () as r, 'INSERT INTO center_verifications (center_id, legal_name, business_reg_type, business_reg_number, mayors_permit_number, owner_name, owner_role, contact_email, contact_phone, address, agency, agency_number, social_url, years_operating, notes, submitted_at, reviewed_at, reviewed_by, updated_at) VALUES (' || concat_ws(', ', coalesce('''' || replace(("center_id")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("legal_name")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("business_reg_type")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("business_reg_number")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("mayors_permit_number")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("owner_name")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("owner_role")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("contact_email")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("contact_phone")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("address")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("agency")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("agency_number")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("social_url")::text, '''', '''''') || '''', 'NULL'), coalesce(("years_operating")::text, 'NULL'), coalesce('''' || replace(("notes")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace((to_char("submitted_at" at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace((to_char("reviewed_at" at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("reviewed_by")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace((to_char("updated_at" at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text, '''', '''''') || '''', 'NULL')) || ');' as sql from (select * from public.center_verifications) x
union all
select 40 as n, row_number() over () as r, 'INSERT INTO center_documents (id, center_id, kind, path, file_name, created_at) VALUES (' || concat_ws(', ', coalesce('''' || replace(("id")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("center_id")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("kind")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("path")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace(("file_name")::text, '''', '''''') || '''', 'NULL'), coalesce('''' || replace((to_char("created_at" at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))::text, '''', '''''') || '''', 'NULL')) || ');' as sql from (select * from public.center_documents order by created_at) x
) s order by n, r;
